enum
{
    ATTRIB_AIR,
    ATTRIB_SPEED,
    ATTRIB_ROTATE,
    ATTRIB_BALANCE,
    NUM_ATTRIBS
};

enum cheats_enum
{
    CHEAT_RAINBOW,
    CHEAT_TRIPPY,
    CHEAT_FREAK_BOY,
    CHEAT_TONY_HAWK,
    CHEAT_TIKI_GOD,
    CHEAT_TRAVIS_PASTRANA,
    CHEAT_FPS_CAM,
    CHEAT_INCREASE_BALANCE,
    CHEAT_SUPER_BALANCE,
    CHEAT_INCREASE_JUMP,
    CHEAT_SUPER_JUMP
};

class Cheat
{
    bool locked;
    bool on;

public:
    bool isOn() const { return on; }
};

class SpecialMeter
{
public:
    bool CanRegionLink(void) const;
};

class kellyslater_controller
{
    char pad0[5704];
    SpecialMeter specialMeter;
    char pad1[1227];
    float attribs[4];

public:
    float GetAttribs(int attr);
};

extern Cheat g_session_cheats[];
extern float air_base;
extern float speed_base;
extern float rotate_base;
extern float special_meter_bonus;
extern float jump_cheat_inc;
extern float balance_cheat_inc;
extern float super_jump_cheat_inc;
extern float super_balance_cheat_inc;

float kellyslater_controller::GetAttribs(int attr) 
{ 
    float temp_attrib = attribs[attr];

    if (attr == ATTRIB_BALANCE && g_session_cheats[CHEAT_SUPER_JUMP].isOn())
        temp_attrib += super_balance_cheat_inc * (1.0f - air_base);
    else if (attr == ATTRIB_AIR && g_session_cheats[CHEAT_INCREASE_JUMP].isOn())
        temp_attrib += jump_cheat_inc * (1.0f - air_base);

    if (attr == ATTRIB_BALANCE && g_session_cheats[CHEAT_SUPER_BALANCE].isOn())
        temp_attrib += super_jump_cheat_inc * (1.0f - air_base);
    else if (attr == ATTRIB_BALANCE && g_session_cheats[CHEAT_INCREASE_BALANCE].isOn())
        temp_attrib += balance_cheat_inc * (1.0f - air_base);

    if (specialMeter.CanRegionLink())
    {
        if (attr == ATTRIB_AIR)
            temp_attrib += special_meter_bonus * (1.0f - air_base); 
        else if (attr == ATTRIB_SPEED)
            temp_attrib += special_meter_bonus * (1.0f - speed_base); 
        else if (attr == ATTRIB_ROTATE)
            temp_attrib += special_meter_bonus * (1.0f - rotate_base); 
        else
            temp_attrib += special_meter_bonus;
    }

    return temp_attrib; 
}
